  const shellOut = document.createElement('pre');
  shellOut.style.cssText = 'margin:0 0 6px;padding:8px;border:1px solid var(--border);border-radius:6px;background:var(--bg-well);color:var(--text-secondary);font-family:ui-monospace,Consolas,monospace;font-size:11px;white-space:pre-wrap;word-break:break-word;max-height:160px;overflow:auto;';
  shellOut.textContent = String(props.connectionState || 'disconnected') + '\ntype help';
