  shellInput.placeholder = '> command';
  shellInput.style.cssText = 'width:100%;box-sizing:border-box;padding:6px 8px;background:none;border:1px solid var(--border);border-radius:6px;color:var(--text-primary);font-family:ui-monospace,Consolas,monospace;font-size:12px;';
  shellSection.append(shellHeader, shellOut, shellInput);
  const shellHistory = shellOut.textContent.split('\n');
  copyBtn.addEventListener('click', async () => {
    try {
      await navigator.clipboard.writeText(shellHistory.join('\n'));
      copyBtn.textContent = 'Copied';
    } catch (err) {
      copyBtn.textContent = 'Copy failed';
    }
    setTimeout(() => { copyBtn.textContent = 'Copy'; }, 1500);
  });
  function shellPrint(text) {
    shellHistory.push(...String(text).split('\n'));
    while (shellHistory.length > 200) shellHistory.shift();
    shellOut.textContent = shellHistory.join('\n');
    shellOut.scrollTop = shellOut.scrollHeight;
  }
  // A terminal on the link: everything that crosses it, both ways.
  // `> ` is what this browser sent -- typed here, or put on a wire into
  // the board's socket -- and `< ` is what the board said, replies (ok,
  // error:) included, plus what it prints on its own: a circuit's [USB]
  // line, [CAN] tx/rx for what it put on or took off the bus, a node
  // heard. Only the app's own housekeeping stays out (pin polling, this
  // dialog's status refreshes -- sent quiet, see serialConsole.js), as do
  // the pin-state JSON and expander chatter.
  // The socket is a channel of the board's shell, and the board announces
  // its traffic to everyone on the shell itself as `<id>@socket><text>`:
  // node <id> put <text> on its socket -- its own id for what this
  // board's circuit sent, the sender's for what reached it (see conucon's
  // socketOut / socketIn). Those lines are shown as the board says them;
  // everything else gets `> ` (sent from here) or `< `.
  function shellLine({ line, outgoing }) {
    if (/^\w+@socket>/.test(line) || /^socket (in|out): /.test(line)) return line;
    return (outgoing ? '> ' : '< ') + line;
  }
  if (helpers.console.subscribeLines) {
    const stopLines = helpers.console.subscribeLines((event) => {
      if (!container.isConnected) { stopLines(); return; }
      const line = event.line;
      if (event.quiet || line.startsWith('{') || line.startsWith('[TCA9554]')) return;
      shellPrint(shellLine(event));
    });
  }
  async function runShell(line, opts) {
    if (!helpers.console.shell) return { ok: false, lines: [], error: 'no shell in this noditron' };
    return helpers.console.shell(line, opts);
  }
  // Where the shell stands, as a path in the tree of nodes and their
  // blocks: `/` is this board, `/cnc` the CNC built into it, `/joystick`
  // (or `/855691c0`) another node, reached over the bus through this
  // board, `/85568abc/cnc` the CNC in that one; below any of them, the
  // groups of its settings tree (`/cnc/x`, `/can`). `cd <path>`, `cd ..`,
  // `cd` / `cd /`, `pwd`; `<path>><line>` runs one line there without
  // going (`/85568abc/cnc>ls`), and a line starting with `/` alone runs at
  // the top (`/ping`). Kept here, not on the board: the app's own polls
  // share the console and must keep reaching this board itself. A line
  // goes out as the board needs it: `node <id> ` in front for another
  // node, `cnc ` for a CNC (which answers in-band, its grbl lines then the
  // board's ok), and ls / get / set with the location in front of their
  // path (`ls` in /cnc/x is `cnc ls x`).
  const shellTop = () => ({ node: null, cnc: false, groups: [] });
  let shellCwd = shellTop();
  let shellHasCnc = null;  // whether this board answers `cnc` (its help lists it); asked once
  const shellKnownNodes = new Set();
  const shellWhere = (at) => '/' + [at.node, at.cnc ? 'cnc' : null, ...at.groups].filter(Boolean).join('/');
  const shellPrompt = () => { shellInput.placeholder = (shellCwd.node || shellCwd.cnc || shellCwd.groups.length ? shellWhere(shellCwd) : '') + '> command'; };
  async function boardHasCnc() {
    if (shellHasCnc === null) {
      try {
        const r = await runShell('help', { timeoutMs: 2000, quiet: true });
        shellHasCnc = (r.lines || []).some((l) => /^cnc\s/.test(l));
      } catch (_) {
        return false;
      }
    }
    return shellHasCnc;
  }
  async function isNode(word) {
    if (shellKnownNodes.has(word)) return true;
    const r = await runShell('node ' + word + ' ?', { timeoutMs: 3500, quiet: true });
    if (r.ok) shellKnownNodes.add(word);
    return Boolean(r.ok);
  }
  async function isLocalGroup(words) {
    const r = await runShell('ls ' + words.join(' '), { timeoutMs: 2000, quiet: true });
    return Boolean(r.ok) && !(r.lines || []).some((l) => /^error/.test(l));
  }
  // The board's line for one typed at `at`.
  function shellLineFor(at, line) {
    const sub = at.groups.join(' ');
    let out = line;
    const verb = /^(ls|get|set)(\s+|$)(.*)$/i.exec(line);
    if (verb && sub) out = verb[1] + ' ' + sub + (verb[3] ? ' ' + verb[3] : '');
    if (at.cnc) out = 'cnc ' + out;
    if (at.node) out = 'node ' + at.node + ' ' + out;
    return out;
  }
  // The place `arg` names from `base`, or { error }.
  async function shellResolve(arg, base) {
    const at = arg.startsWith('/') ? shellTop() : { node: base.node, cnc: base.cnc, groups: [...base.groups] };
    for (const token of arg.split(/[\s/]+/).filter(Boolean)) {
      if (token === '.') continue;
      if (token === '..') {
        if (at.groups.length) at.groups.pop();
        else if (at.cnc) at.cnc = false;
        else at.node = null;
        continue;
      }
      for (const word of token.split('.').filter(Boolean)) {
        const w = word.toLowerCase();
        const atTop = !at.node && !at.cnc && !at.groups.length;
        if (atTop && w === 'cnc' && (await boardHasCnc())) {
          at.cnc = true;  // this board's own CNC; on a board without one, `cnc` is a node's name below
        } else if (atTop) {
          if (await isLocalGroup([w])) at.groups.push(w);
          else if (await isNode(word)) at.node = word;
          else return { error: 'no such group or node: ' + word };
        } else if (at.node && !at.cnc && !at.groups.length && w === 'cnc') {
          at.cnc = true;
        } else {
          // grbl's groups (a CNC's, or anything on another node) are not
          // asked for: a wrong one shows at the first ls.
          if (!at.node && !at.cnc && !(await isLocalGroup([...at.groups, w]))) return { error: 'no such group: ' + [...at.groups, w].join('.') };
          at.groups.push(w);
        }
      }
    }
    return { at };
  }
  shellInput.addEventListener('keydown', async (event) => {
    if (event.key !== 'Enter') return;
    const line = shellInput.value.trim();
    if (!line) return;
    shellInput.value = '';
    try {
      const cd = /^cd(?:\s+(.*))?$/.exec(line);
      if (cd) {
        shellPrint('> ' + line);
        const r = await shellResolve((cd[1] || '/').trim(), shellCwd);
        if (r.error) { shellPrint('error: ' + r.error); return; }
        shellCwd = r.at;
        shellPrompt();
        shellPrint(shellWhere(shellCwd));
        return;
      }
      if (line === 'pwd') { shellPrint('> pwd'); shellPrint(shellWhere(shellCwd)); return; }
      let out;
      const oneShot = /^(\/[^\s>]*)>\s*(.*)$/.exec(line);
      if (oneShot) {
        const r = await shellResolve(oneShot[1], shellCwd);
        if (r.error) { shellPrint('> ' + line); shellPrint('error: ' + r.error); return; }
        out = shellLineFor(r.at, oneShot[2]);
      } else if (line.startsWith('/')) {
        out = line.slice(1).trim();  // the top, whatever the location
      } else {
        out = shellLineFor(shellCwd, line);
      }
      // The line and its reply reach the box through the subscription
      // above; only a link that gives nothing back needs saying so.
      const r = await runShell(out);
      if (!r.ok && r.error === 'no reply') shellPrint('(no reply)');
    } catch (err) {
      shellPrint('error: ' + err.message);
    }
  });

  let netTimer = null;
  let netBusy = false;
  // The WiFi switch was turned on but the board has no network saved yet:
  // keep it on and show the controls until a network is joined.
  let staSetup = false;
  async function refreshConnectivity() {
    if (netBusy || !container.isConnected) return;
    if (helpers.serial.isFlashing && helpers.serial.isFlashing()) return;
    netBusy = true;
    try {
      // Polls are short: a board without the shell's ok terminator (build
      // 20260924g) answers at once and then leaves the reader waiting.
      const asJson = (lines, pick) => lines.map((l) => { try { return JSON.parse(l); } catch (_) { return null; } }).find(pick);
      const nodes = await runShell('nodes', { timeoutMs: 1500, quiet: true });
      let nodeLines = nodes.lines.filter((l) => /^(noditron|logic|cnc|node) [0-9a-f]{8}/.test(l));
      const nodesJson = asJson(nodes.lines, (j) => j && Array.isArray(j.nodes));
      if (!nodeLines.length && nodesJson) {
        nodeLines = nodesJson.nodes.map((n) => n.type + ' ' + n.id + ' v' + n.version
          + (n.self ? ' self' : ' seen ' + Math.round((n.ageMs || 0) / 1000) + 's ago via ' + (n.via || 'can')));
      }
      nodesEl.textContent = nodeLines.length ? 'Nodes:\n' + nodeLines.join('\n') : 'Nodes: ' + (nodes.lines.length ? 'unreadable reply' : nodes.error || 'no reply');
      // This node's own id (`... self`), kept on the block: it is what
      // another board's socket is told to deliver to (see devkitCircuit's
      // socketLinksFor).
      const selfLine = nodeLines.find((l) => /\bself\b/.test(l));
      const selfId = selfLine && (selfLine.match(/^(?:logic|cnc|node) ([0-9a-f]{8})/) || [])[1];
      if (selfId && props.nodeId !== selfId) helpers.setProp('nodeId', selfId);
      const status = await runShell('wifi status', { timeoutMs: 1500, quiet: true });
      let sta = status.lines.find((l) => /^sta (on|off)/.test(l)) || '';
      let ap = status.lines.find((l) => /^ap (on|off)/.test(l)) || '';
      const statusJson = asJson(status.lines, (j) => j && j.ap && j.sta);
      if (!sta && !ap && statusJson) {
        // Build 20260924g: JSON, and no on/off switches yet -- both radios are on.
        ap = 'ap on: ' + statusJson.ap.ssid + ' ' + statusJson.ap.ip + ' clients=' + statusJson.ap.clients;
        sta = statusJson.sta.connected
          ? 'sta on: connected ' + statusJson.sta.ssid + ' ip=' + statusJson.sta.ip + ' rssi=' + statusJson.sta.rssi
          : statusJson.sta.saved ? 'sta on: disconnected, saved ' + statusJson.sta.ssid : 'sta on: disconnected, no network saved';
      }
      if (sta.startsWith('sta on')) staSetup = false;
      staRow.box.checked = staSetup || sta.startsWith('sta on');
      staRow.status.textContent = sta.replace(/^sta (on|off):?\s*/, '') || (sta ? (staRow.box.checked ? 'on' : 'off') : '');
      apRow.box.checked = ap.startsWith('ap on');
      apRow.status.textContent = ap.replace(/^ap (on|off):?\s*/, '') || (ap ? (apRow.box.checked ? 'on' : 'off') : '');
      staControls.style.display = staRow.box.checked ? 'flex' : 'none';
      const all = nodes.lines.concat(status.lines);
      // An old build answers a shell word with grbl's numeric error or with JSON; a
      // board that is busy (restarting its radio, say) answers nothing for a while.
      if (!nodes.ok && !status.ok) {
        if (all.some((l) => /^error:\d+$/.test(l) || l.startsWith('{'))) netHint.textContent = 'This firmware has no shell yet -- switches and scan need the update above.';
        else netHint.textContent = 'No answer right now -- the board may be restarting its radio; trying again.';
      } else if (/^No answer right now/.test(netHint.textContent)) {
        netHint.textContent = '';
      }
    } catch (err) {
      netHint.textContent = err.message;
    } finally {
      netBusy = false;
    }
  }
  function startConnectivity() {
    netSection.style.display = '';
    refreshConnectivity();
    if (netTimer) return;
    netTimer = setInterval(() => {
      if (!container.isConnected || netSection.style.display === 'none') {
        clearInterval(netTimer);
        netTimer = null;
        return;
      }
      refreshConnectivity();
    }, 10000);
  }
  apRow.box.addEventListener('change', async () => {
    const r = await runShell(apRow.box.checked ? 'ap on' : 'ap off');
    if (!r.ok) netHint.textContent = r.error;
    refreshConnectivity();
  });
  staRow.box.addEventListener('change', async () => {
    if (!staRow.box.checked) {
      staSetup = false;
      const r = await runShell('wifi off');
      if (!r.ok) netHint.textContent = r.error;
      refreshConnectivity();
      return;
    }
    const r = await runShell('wifi on');
    if (!r.ok && /no network saved/i.test(r.error || '')) {
      staSetup = true;
      staControls.style.display = 'flex';
      netHint.textContent = 'No network saved yet: scan, pick one and enter its password.';
      return;
    }
    if (!r.ok) netHint.textContent = r.error;
    refreshConnectivity();
  });
  scanBtn.addEventListener('click', async () => {
    scanBtn.disabled = true;
    netHint.textContent = 'Scanning...';
    try {
      let r = await runShell('wifi list');
      for (let i = 0; i < 15 && r.lines.some((l) => l.startsWith('scanning')); i += 1) {
        await new Promise((resolve) => setTimeout(resolve, 1000));
        r = await runShell('wifi list');
      }
      const nets = r.lines.map((l) => l.match(/^(\d+) (.+?) (-?\d+)dBm (secured|open)/)).filter(Boolean);
      netSelect.replaceChildren();
      for (const m of nets) {
        const option = document.createElement('option');
        option.value = m[2];
        option.textContent = m[2] + ' (' + m[3] + ' dBm, ' + m[4] + ')';
        netSelect.appendChild(option);
      }
      netHint.textContent = nets.length ? nets.length + ' network(s) in range.' : (r.error || 'No networks found.');
    } catch (err) {
      netHint.textContent = err.message;
    } finally {
      scanBtn.disabled = false;
    }
  });
  joinBtn.addEventListener('click', async () => {
    const ssid = netSelect.value;
    if (!ssid) { netHint.textContent = 'Scan and pick a network first.'; return; }
    joinBtn.disabled = true;
    try {
      const sel = await runShell('wifi select ' + ssid);
      if (!sel.ok) { netHint.textContent = sel.error; return; }
      const pw = await runShell('wifi pw ' + pwInput.value);
      netHint.textContent = pw.ok ? 'Joining ' + ssid + '...' : pw.error;
      if (pw.ok) staSetup = false;
      pwInput.value = '';
      setTimeout(refreshConnectivity, 3000);
    } finally {
      joinBtn.disabled = false;
    }
  });
  forgetBtn.addEventListener('click', async () => {
    await runShell('wifi forget');
    refreshConnectivity();
  });


  container.appendChild(shellSection);
  function log(line) {
    shellPrint(line);
  }

  function showRunning(info) {
    statusEl.textContent = 'grbl v' + info.version + ' build ' + info.build + ' running.';
    machineState.textContent = 'state ' + (info.machineState || '?');
    machineSection.style.display = '';
    showMachinePage(info.ip);
    startConnectivity();
  }

  function reportIdentified(info) {
    if (info.kind === 'cnc') {
      log('ping: grbl v' + info.version + ' build ' + info.build + ', state ' + (info.machineState || '?') + '.');
      helpers.setProp('connectionState', 'connected:running');
      // Who this node is, for another board's socket to address (see
      // devkitCircuit's socketLinksFor).
      if (info.node) helpers.setProp('nodeId', info.node);
      if (info.nodeName) helpers.setProp('nodeName', info.nodeName);
      showRunning(info);
      showFirmware('running', info);
      return;
    }
    statusEl.textContent = 'That is a Logic Module, not a CNC module -- install the CNC firmware below to make it one.';
    log('ping answered as a Logic Module (build ' + info.build + ').');
    helpers.setProp('connectionState', 'connected:unknown');
    showFirmware('logic', info);
  }

  // The one place that decides what is on the other end: the console's
  // own 'ping' first (harmless on a running board), and only when nothing
  // answers, over USB, the chip itself through its ROM bootloader -- that
  // tells a blank board from a dead link, and which family the firmware
  // has to be for. Reused after Connect and again after an install once
  // the board has had a moment to boot.
  async function afterPortOpen() {
    statusEl.textContent = 'Connected -- asking who is there...';
    const link = helpers.serial.linkKind();
    try {
      const info = await helpers.console.identify();
      if (info.verified) { reportIdentified(info); return; }
    } catch (err) {
      log('Console check failed: ' + err.message);
    }
    if (link === 'can') {
      statusEl.textContent = 'Reached over CAN through ' + ((helpers.serial.getSession() || {}).target || 'another board') + ', but it did not answer. Its firmware needs the node protocol (CNC build 20260927b or later): connect it over USB once to install.';
      helpers.setProp('connectionState', 'connected:unknown');
      showFirmware('none', null);
      return;
    }
    let chipName = '';
    if (link === 'serial') {
      try {
        const detected = await helpers.serial.detectChip(log);
        chipName = detected.chipName;
        log('Detected ' + detected.chipName + ' (bootloader @ 0x' + detected.bootloaderOffset.toString(16) + ').');
        // Detecting left the board in its ROM bootloader, not running
        // whatever it has; identify() resets it out (see serialFlash's
        // reopenPlain) and asks once more, so a board that only needed
        // longer to boot says so here instead of being reported as blank.
        try {
          const after = await helpers.console.identify();
          if (after.verified) { reportIdentified(after); return; }
        } catch (err) {
          log('Console re-check failed: ' + err.message);
        }
      } catch (err) {
        log('Chip detect failed: ' + err.message);
      }
    }
    statusEl.textContent = (chipName ? chipName + ' detected, but ' : 'Connected, but ') + 'nothing answered as a CNC module. Its firmware may predate the module shell (build 20260925a), or be missing -- install it below.';
    helpers.setProp('connectionState', chipName ? 'connected:needs-firmware:' + chipName : 'connected:unknown');
    showFirmware('none', null);
  }

  const existing = helpers.serial.getSession();
  if (existing) {
    disconnectBtn.disabled = false;
    connectBtn.disabled = true;
    wifiBtn.disabled = true;
    afterPortOpen();
  } else {
    statusEl.textContent = 'Not connected.';
  }

  connectBtn.addEventListener('click', async () => {
    connectBtn.disabled = true;
    wifiBtn.disabled = true;
    try {
      await helpers.serial.connect(log);
      log('Serial port opened.');
      disconnectBtn.disabled = false;
      await afterPortOpen();
    } catch (err) {
      statusEl.textContent = 'Connect failed: ' + err.message;
      connectBtn.disabled = !serialOk;
      wifiBtn.disabled = false;
    }
  });

  wifiBtn.addEventListener('click', async () => {
    if (!helpers.serial.connectWifi) { log('This noditron has no WiFi link yet.'); return; }
    const last = (helpers.serial.rememberedWifi && helpers.serial.rememberedWifi()) || '192.168.0.1';
    const host = window.prompt('Board address: its IP or name on your network, or 192.168.0.1 on its own access point.', last);
    if (!host) return;
    wifiBtn.disabled = true;
    connectBtn.disabled = true;
    try {
      await helpers.serial.connectWifi(host, log);
      disconnectBtn.disabled = false;
      await afterPortOpen();
    } catch (err) {
      statusEl.textContent = 'WiFi connect failed: ' + err.message;
      log('WiFi connect failed: ' + err.message);
      wifiBtn.disabled = false;
      connectBtn.disabled = !serialOk;
    }
  });

  disconnectBtn.addEventListener('click', async () => {
    helpers.console.close();
    await helpers.serial.disconnect(true);
    statusEl.textContent = 'Disconnected.';
    connectBtn.disabled = !serialOk;
    wifiBtn.disabled = false;
    disconnectBtn.disabled = true;
    machineSection.style.display = 'none';
    firmwareSection.style.display = 'none';
    netSection.style.display = 'none';
    helpers.setProp('connectionState', 'disconnected');
  });
}

